      ` ${TRAILER_KEY}: alpha`,
      '-old',
      '+new',
      '',
    ].join('\n')
    const out = applyTrailer(message, 'alpha')
    expect(out).not.toBeNull()
    expect(out!.split('\n').findIndex((l) => l.startsWith(TRAILER_KEY))).toBeLessThan(
      out!.split('\n').findIndex((l) => l.includes('>8')),
    )
  })

